from brain.alphas import alpha
import numpy as np
import numpy.typing as npt


@alpha(
    data=[
        "anl10_analyst_innovation_dps_revise_ratio_to_consensus_fy1",
        "anl10_analyst_innovation_sal_revise_ratio_to_consensus_fy1",
        "mdl26_surprise_60_q",
    ],
    store=[],
)
def alpha_v006(data, store) -> npt.NDArray[np.float32]:
    def cs_rank(arr):
        arr = np.where(np.isfinite(arr), arr, np.nan).astype(np.float64)
        valid = ~np.isnan(arr)
        if not valid.any():
            return np.full_like(arr, np.nan)
        out = np.full_like(arr, np.nan)
        out[valid] = np.argsort(np.argsort(arr[valid])) / max(valid.sum() - 1, 1)
        return out

    def ts_mean(arr, window):
        if arr.shape[0] < window:
            return np.full_like(arr[-1], np.nan)
        return np.nanmean(arr[-window:], axis=0)

    # analyst10 innovation: 20 day ts_mean (shorter for more signal)
    dps_raw = data.anl10_analyst_innovation_dps_revise_ratio_to_consensus_fy1.astype(np.float64)
    sal_raw = data.anl10_analyst_innovation_sal_revise_ratio_to_consensus_fy1.astype(np.float64)
    dps_20d = ts_mean(dps_raw, 20)
    sal_20d = ts_mean(sal_raw, 20)

    # mdl26_surprise_60_q: 直接用最新截面
    surprise = data.mdl26_surprise_60_q[-1].astype(np.float64)

    r1 = cs_rank(dps_20d)
    r2 = cs_rank(sal_20d)
    r3 = cs_rank(surprise)

    signal = np.nanmean(np.stack([r1, r2, r3], axis=0), axis=0)
    u = data.universe[-1].astype(bool)
    signal = signal.copy()
    signal[~u] = np.nan
    return signal.astype(np.float32)

