    def z(a):
        a=np.asarray(a,dtype=np.float64); v=np.isfinite(a); m=np.nanmean(a); s=np.nanstd(a)
        if not np.isfinite(s) or s<1e-9: return np.zeros_like(a)
        return np.where(v,(a-m)/s,0.0)
    # No rolling buffer - decay=2 controls temporal smoothing
    # 3-field fusion: val(undervalued)+arm(bullish)+chg(momentum)
    c=z(data.rel_val_region_rank_score_4[-1])+z(data.analyst_revisions_score_2[-1])+z(data.arm_score_change_30d_3[-1])
    u=data.universe[-1]; c=np.where(u.astype(bool),c,np.nan); c[~np.isfinite(c)]=0.0
    return c.astype(np.float32)

